def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = set(v for row in grid for v in row)
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    for r in range(h - 1):
        for c in range(w - 1):
            color = grid[r][c]
            if color != bg and all(grid[rr][cc] == color for rr in (r, r + 1) for cc in (c, c + 1)):
                cells = []
                cells.extend((r - 1, cc) for cc in (c, c + 1))
                cells.extend((r + 2, cc) for cc in (c, c + 1))
                cells.extend((rr, c - 1) for rr in (r, r + 1))
                cells.extend((rr, c + 2) for rr in (r, r + 1))
                for rr, cc in cells:
                    if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = 2
    return out
